import cv2
import numpy as np

img = cv2.imread('/work/observations/obs_0062.png')

for r in [340, 360, 380, 400, 420, 440, 460, 480, 500]:
    woods = []
    for x in range(260, 310):
        b, g, red = int(img[r, x, 0]), int(img[r, x, 1]), int(img[r, x, 2])
        # wood color in BGR: b in [110, 130], g in [140, 160], red in [165, 185]
        if 105 <= b <= 135 and 135 <= g <= 165 and 165 <= red <= 185:
            woods.append(x)
    if woods:
        print(f'r={r}: wood cols min={min(woods)}, max={max(woods)}')
    else:
        print(f'r={r}: no wood found')
